void test__test_range__test_containment(void) {
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, true }, 5), KOBEL_STR("5 in 0..10"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, true }, 0), KOBEL_STR("0 in 0..10"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, true }, 10), KOBEL_STR("10 in 0..10"));
testsupport__assert__assert_true(!(std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, true }, 11)), KOBEL_STR("!(11 in 0..10)"));
testsupport__assert__assert_true(!std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, true }, 11), KOBEL_STR("11 !in 0..10"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, false }, 9), KOBEL_STR("9 in 0..<10"));
testsupport__assert__assert_true(!(std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, false }, 10)), KOBEL_STR("!(10 in 0..<10)"));
testsupport__assert__assert_true(!std__range__Range_i32_contains(&(std__range__Range_i32){ 0, 10, false }, 10), KOBEL_STR("10 !in 0..<10"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 10, 0, true }, 5), KOBEL_STR("5 in 10..0"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 10, 0, true }, 10), KOBEL_STR("10 in 10..0"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 10, 0, true }, 0), KOBEL_STR("0 in 10..0"));
testsupport__assert__assert_true(!std__range__Range_i32_contains(&(std__range__Range_i32){ 10, 0, true }, 11), KOBEL_STR("11 !in 10..0"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 10, 0, false }, 10), KOBEL_STR("10 in 10..<0"));
testsupport__assert__assert_true(std__range__Range_i32_contains(&(std__range__Range_i32){ 10, 0, false }, 1), KOBEL_STR("1 in 10..<0"));
testsupport__assert__assert_true(!std__range__Range_i32_contains(&(std__range__Range_i32){ 10, 0, false }, 0), KOBEL_STR("0 !in 10..<0"));
testsupport__assert__assert_true(std__range__Range_char_contains(&(std__range__Range_char){ 'a', 'z', true }, 'm'), KOBEL_STR("'m' in 'a'..'z'"));
testsupport__assert__assert_true(std__range__Range_char_contains(&(std__range__Range_char){ 'a', 'z', true }, 'a'), KOBEL_STR("'a' in 'a'..'z'"));
testsupport__assert__assert_true(std__range__Range_char_contains(&(std__range__Range_char){ 'a', 'z', true }, 'z'), KOBEL_STR("'z' in 'a'..'z'"));
testsupport__assert__assert_true(!std__range__Range_char_contains(&(std__range__Range_char){ 'a', 'z', true }, 'A'), KOBEL_STR("'A' !in 'a'..'z'"));
std__range__Range_i32 r = (std__range__Range_i32){ 10, 20, true };
testsupport__assert__assert_true(std__range__Range_i32_contains(&r, 15), KOBEL_STR("15 in r"));
testsupport__assert__assert_true(!std__range__Range_i32_contains(&r, 25), KOBEL_STR("25 !in r"));
std__range__Range_usz r_usz = (std__range__Range_usz){ ((size_t)0ULL), ((size_t)5ULL), false };
testsupport__assert__assert_true(std__range__Range_usz_contains(&r_usz, ((size_t)0ULL)), KOBEL_STR("0UZ in r_usz"));
testsupport__assert__assert_true(std__range__Range_usz_contains(&r_usz, ((size_t)4ULL)), KOBEL_STR("4UZ in r_usz"));
testsupport__assert__assert_true(!std__range__Range_usz_contains(&r_usz, ((size_t)5ULL)), KOBEL_STR("5UZ !in r_usz"));
std__range__Range_i32 r_empty = (std__range__Range_i32){ 5, 5, false };
testsupport__assert__assert_true(!std__range__Range_i32_contains(&r_empty, 5), KOBEL_STR("5 !in r_empty"));
testsupport__assert__assert_true(std__range__Range_i32_equals(&r, (std__range__Range_i32){ 10, 20, true }), KOBEL_STR("r == 10..20"));
testsupport__assert__assert_true(!std__range__Range_i32_equals(&r, (std__range__Range_i32){ 10, 20, false }), KOBEL_STR("r != 10..<20"));
}

